import csv, statistics
from collections import defaultdict
cat = {r['point_uri'].split('#')[1]: r['timeseries_id'] for r in csv.DictReader(open(CATALOG_CSV))}
vals = list(csv.DictReader(open(VALUES_CSV)))

def stats(name, lo='2018-07-01', hi='2019-01-01'):
    sid = cat[name]
    v = [float(r['value']) for r in vals if r['timeseries_id']==sid and lo<=r['timestamp']<hi]
    return len(v), round(statistics.mean(v),2), round(statistics.pstdev(v),3)

for z in ['Zone_F3_Z01.Zone_Air_Temperature_Sensor','Zone_F3_Z02.Zone_Air_Temperature_Sensor',
          'Zone_F2_Z02.Zone_Air_Temperature_Sensor','VAV_F3_Z01.Damper_Position_Setpoint',
          'VAV_F3_Z02.Damper_Position_Setpoint']:
    n,m,s = stats(z)
